-- 154: Grow the Landscape plants database toward a local nursery's landscape range,
-- and use the category names Las Vegas pros know (Desert Accent instead of Accent).
-- Care notes are our own. Safe to re-run: existing plants are skipped.

UPDATE public.trade_catalog_items SET category = 'Desert Accent'
WHERE trade = 'landscape' AND category = 'Accent';

-- Nurseries sell the sago with palms.
UPDATE public.trade_catalog_items SET category = 'Palm'
WHERE trade = 'landscape' AND lower(name) = 'sago palm';

ON CONFLICT DO NOTHING;
